\subsection{Mathematical statement of the claimed result}
\paragraph{Result 1.} Take a bounded measurable radial potential \(v:\mathbb R^3\to[0,\infty)\), supported in a ball of finite radius and nonzero on a set of positive measure. On \((\mathbb R/L\mathbb Z)^3\), use the symmetric \(N\)-particle Hamiltonian
\[
 H_{N,L}=-\sum_i\Delta_i+\sum_{i<j}v_L(x_i-x_j),\qquad
 v_L(x)=\sum_{k\in\mathbb Z^3}v(x+Lk).
\]
Let \(\gamma^{(1)}_{N,L,T}\) be the canonical state's one-particle matrix, of trace \(N\), and \(u_0=L^{-3/2}\). The claim provides \(\rho_*(v),c_*(v)>0\) such that every \(0<\rho<\rho_*\) has a finite \(L_0(\rho,v)\), with
\[
 L\ge L_0,\quad\rho/2\le N/L^3\le2\rho,\quad0\le T\le\rho^2
 \quad\Longrightarrow\quad
 \frac{\langle u_0,\gamma^{(1)}_{N,L,T}u_0\rangle}{N}\ge c_*.
\]
The positive fraction is uniform throughout the indicated dilute density range.

\paragraph{Result 2.} Fix exclusion distance \(a>0\). On the three-dimensional torus of side \(L\), the hard-sphere Hamiltonian is the symmetric Dirichlet kinetic operator on configurations with every interparticle torus distance greater than \(a\). Let \(\gamma^{(1)}_{N,L,T}\) be the canonical Gibbs one-particle matrix, of trace \(N\), and \(u_{0,L}=L^{-3/2}\). The source asserts that some \(\rho_*(a)>0\) has the property
\[
 0<\rho<\rho_*(a)\quad\Longrightarrow\quad
 \exists T(a,\rho)>0:\quad
 \liminf_{L\to\infty,\ N/L^3\to\rho}
 \frac{\langle u_{0,L},\gamma^{(1)}_{N,L,T}u_{0,L}\rangle}{N}>0.
\]
Here \(a,\rho,T\) remain fixed during the thermodynamic limit.

