\[
 B(\Psi)=N^{-1}\langle L^{-3/2},\gamma^{(1)}_\Psi L^{-3/2}\rangle,
 \qquad\operatorname{Tr}\gamma^{(1)}_\Psi=N.
\]
The claimed universal constants \(\varepsilon_0,c_0>0\) give
\[
 \rho a^3<\varepsilon_0,\quad N_k,L_k\to\infty,\quad N_k/L_k^3\to\rho
 \quad\Longrightarrow\quad\liminf_k B(\Psi_k)\ge c_0
\]
for every choice of ground vectors, allowing complex vectors and degeneracy.

\paragraph{Result 4.} For the three-dimensional periodic hard-sphere Bose gas of exclusion distance \(a>0\), let \(\mathcal G_{N,L,a}\) be all trace-one states supported on the lowest eigenspace, and \(n_{\Gamma,L}(k)\) the occupation of \(L^{-3/2}e^{ik\cdot x}\). Define
\[
 g(t)=\frac{|t|^2+1}{2\sqrt{|t|^4+2|t|^2}}-\frac12,\qquad
 d\nu_{\mathrm{Bog}}(t)=\frac{(8\pi)^{3/2}}{(2\pi)^3}g(t)\,dt.
\]
For each bounded continuous real \(f\) and \(\varepsilon>0\), the source gives \(\rho_0(a,f,\varepsilon)>0\). If \(0<\rho<\rho_0\), \(\eta=\rho a^3\), and \(N_j,L_j\to\infty\), \(N_j/L_j^3\to\rho\), then
\[
 \limsup_j\sup_{\Gamma\in\mathcal G_{N_j,L_j,a}}
 \left|\frac{\sum_{k\in(2\pi/L_j)\mathbb Z^3,\ k\ne0}
 f(k/\sqrt{8\pi\rho a})n_{\Gamma,L_j}(k)}{N_j\sqrt\eta}
 -\int f\,d\nu_{\mathrm{Bog}}\right|\le\varepsilon.
\]
The measure has total mass \(8/(3\sqrt\pi)\).

\paragraph{Result 5.} Let \(v\ge0\) be bounded, measurable, radial, compactly supported, and nonzero on a positive-measure set. Its scattering length \(a_v>0\) is determined by \((-\Delta+v/2)f=0\), with \(f(x)=1-a_v/|x|\) outside the support. For the periodic symmetric Hamiltonian \(-\sum_i\Delta_i+\sum_{i<j}v_L(x_i-x_j)\), let \(\mathcal G^v_{N,L}\) contain all ground-space trace-one states and \(B_\Gamma=N^{-1}\langle L^{-3/2},\gamma^{(1)}_\Gamma L^{-3/2}\rangle\). For every \(\varepsilon>0\), some \(\rho_0(v,\varepsilon)>0\) satisfies
\[
 0<\rho<\rho_0,\ N_k,L_k\to\infty,\ N_k/L_k^3\to\rho
 \ \Longrightarrow\
 \limsup_k\sup_{\Gamma\in\mathcal G^v_{N_k,L_k}}
 \left|\frac{1-B_\Gamma}{\sqrt{\rho a_v^3}}-\frac8{3\sqrt\pi}\right|\le\varepsilon.
\]
Volume and particle number tend to infinity while density remains fixed.

